package com.juner2026.crabpet;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.ColorDrawable;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;
public class PetService extends Service{ WindowManager wm; CrabView crab; WindowManager.LayoutParams lp; public IBinder onBind(Intent i){return null;} public int onStartCommand(Intent i,int f,int id){show();return START_STICKY;} void show(){if(crab!=null)return; wm=(WindowManager)getSystemService(WINDOW_SERVICE); crab=new CrabView(this); lp=new WindowManager.LayoutParams(150,150,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);lp.gravity=Gravity.TOP|Gravity.START;lp.x=30;lp.y=220;wm.addView(crab,lp);} public void onDestroy(){if(crab!=null)wm.removeView(crab);super.onDestroy();} class CrabView extends View{Paint p=new Paint(3);float dx,dy;long down;int taps;Handler h=new Handler();Runnable anim=()->{invalidate();h.postDelayed(this::invalidate,120);};CrabView(Context c){super(c);p.setAntiAlias(false);setBackground(new ColorDrawable(Color.TRANSPARENT));h.post(anim);} protected void onDraw(Canvas c){super.onDraw(c);float bob=(float)Math.sin(System.currentTimeMillis()/180.0)*4; p.setColor(Color.rgb(240,132,157));c.drawOval(35,55+bob,115,120+bob,p);p.setColor(Color.rgb(255,174,185));c.drawCircle(53,35+bob,22,p);c.drawCircle(97,35+bob,22,p);p.setColor(Color.rgb(45,36,45));c.drawRect(52,72+bob,61,83+bob,p);c.drawRect(89,72+bob,98,83+bob,p);p.setColor(Color.rgb(224,94,125));c.drawRect(20,92+bob,38,101+bob,p);c.drawRect(112,92+bob,130,101+bob,p);c.drawRect(50,120+bob,61,137+bob,p);c.drawRect(89,120+bob,100,137+bob,p);} public boolean onTouchEvent(android.view.MotionEvent e){if(e.getAction()==0){down=System.currentTimeMillis();dx=e.getRawX()-lp.x;dy=e.getRawY()-lp.y;return true;}if(e.getAction()==2){lp.x=(int)(e.getRawX()-dx);lp.y=(int)(e.getRawY()-dy);wm.updateViewLayout(this,lp);return true;}if(e.getAction()==1){long d=System.currentTimeMillis()-down;taps++;invalidate();if(d>700){setVisibility(INVISIBLE);h.postDelayed(()->setVisibility(VISIBLE),2000);}else if(taps>=2){p.setColor(Color.rgb(255,190,220));invalidate();taps=0;}h.postDelayed(()->taps=0,500);return true;}return true;}}}